"""Convert the bundled OFL font to a reproducible, 4-bit embedded glyph atlas.

Each glyph has a fixed cell so the firmware can update a changed character
without measuring a whole line or allocating a framebuffer.
"""

from pathlib import Path
from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).resolve().parents[1]
FONT = ROOT / "third_party/roboto-mono/RobotoMono.ttf"


def main():
    sections = [
        "/* Generated by tools/build_ui_font.py. Roboto Mono: SIL OFL 1.1; see third_party/roboto-mono/OFL.txt. */"
    ]
    for scale, size, width, height in ((1, 11, 6, 12), (2, 20, 12, 20), (3, 30, 18, 30)):
        font = ImageFont.truetype(str(FONT), size)
        font.set_variation_by_axes([700])
        atlas = []
        for code in range(32, 127):
            glyph = chr(code)
            image = Image.new("L", (max(1, font.getbbox(glyph)[2]), height))
            ImageDraw.Draw(image).text(
                (0, -(2 if scale == 1 else 4 if scale == 2 else 6)), glyph, font=font, fill=255
            )
            if image.width > width - 1:
                image = image.resize((width - 1, height), Image.Resampling.LANCZOS)
            cell = Image.new("L", (width, height))
            cell.paste(image, ((width - image.width) // 2, 0))
            coverage = [min(15, (p + 8) // 17) for p in cell.get_flattened_data()]
            atlas.extend((coverage[i] << 4) | coverage[i + 1] for i in range(0, len(coverage), 2))
        rows = [",".join(map(str, atlas[i : i + 32])) for i in range(0, len(atlas), 32)]
        sections.append(
            f"static const uint8_t ui_font_{scale}[{len(atlas)}]={{\n" + ",\n".join(rows) + "\n};"
        )
    (ROOT / "src/ui_font_data.h").write_text("\n".join(sections), encoding="ascii")


if __name__ == "__main__":
    main()
